  /* ---------- Mumbai ---------- */

  { id: "mh-mill-strike", type: "event", domain: "economics", region: "mumbai", title: "The 1982 mill strike and the end of Girangaon", value: 5, cue: "Lower Parel, malls on old mill land, or strikes",
    emoji: "🏭", wiki: "Great Bombay textile strike",
    fact: "On 18 January 1982 nearly 250,000 workers in about 65 Bombay cotton mills went on strike, led by the union leader Datta Samant. The strike lasted well over a year and failed. Most of the mills never fully recovered.",
    why: "The malls and glass towers of Lower Parel stand on old mill land. One failed strike helped change Mumbai from a factory city into an office city.",
    mech: "The workers wanted better pay and the right to choose their own union. The mill owners and the government refused to talk to Samant. Many mills were already old and made little profit. Owners found that the land under a mill was worth more than the cloth it made. Cloth making moved to powerlooms in towns like Bhiwandi, and the land was later sold for offices, malls and flats.",
    models: ["incentives", "second-order-thinking", "opportunity-cost"],
    q: "What happened in the 1982 mill strike, and how did it change Mumbai?",
    a: "Nearly 250,000 mill workers went on strike under Datta Samant in January 1982 for better pay and their own union. The owners did not give in and the strike failed. The mills closed over time, and their valuable land became malls, offices and flats.",
    chain: [["About 250,000 workers struck in 1982", ["250,000", "1982", "strike", "samant"]], ["They wanted better pay and their own union", ["pay", "wage", "union", "bonus"]], ["The owners did not give in and the strike failed", ["failed", "refused", "did not give in", "collapse"]], ["The land was worth more than the cloth", ["land", "mall", "office", "flats", "tower"]]],
    mcq: { q: "What stands today on much of Mumbai's old mill land?", o: ["Malls, offices and tall flats", "New cotton mills with modern machines", "A large public park", "Railway yards"] },
    bring: "At a mall in Lower Parel: “This was a cotton mill. After the 1982 strike, the land became worth more than the cloth.”",
    follow: "Did anyone in your family or building work in the mills?",
    deeper: "The mill area was called Girangaon, the ‘village of mills’. Bombay's first cotton mill was started in 1854 by Cowasji Nanabhai Davar. The strike is often said never to have been formally called off. High Street Phoenix stands on the old Phoenix Mills." },

  { id: "mh-wadia-ships", type: "fact", domain: "business", region: "mumbai", title: "The Wadias: Parsi shipbuilders of Bombay", value: 4, cue: "the Parsis, the naval dockyard, or things built to last",
    emoji: "⛵", wiki: "HMS Trincomalee",
    fact: "In 1736 the Parsi shipbuilder Lovji Nusserwanjee Wadia came from Surat to build ships for the East India Company in Bombay. In 1750 he and his brother built the Bombay dry dock, the first in Asia. HMS Trincomalee, built by the Wadias in 1817, still floats in England today.",
    why: "Bombay once built warships for the British Navy that were better than many built in Britain. One of them is now the oldest British warship still afloat.",
    mech: "British ships were made of oak, and during the wars with Napoleon Britain was running short of it. The Wadias used Malabar teak. Teak has natural oils, so it resists rot and sea worms far better than oak. A teak ship could last many decades. Skilled Parsi shipwrights and good teak gave Bombay an advantage that Britain itself did not have.",
    models: ["lindy-effect", "moat"],
    q: "Why did the British Navy have warships built in Bombay?",
    a: "Britain was short of oak, and the Wadia family of Parsi shipbuilders in Bombay built with Malabar teak, which resists rot and lasts far longer. They came from Surat in 1736 and built Asia's first dry dock in 1750. Their ship Trincomalee of 1817 is still afloat.",
    chain: [["The Wadias came from Surat in 1736", ["wadia", "1736", "surat", "parsi"]], ["They built Asia's first dry dock in 1750", ["dry dock", "1750", "dock"]], ["Teak lasts longer than oak", ["teak", "oak", "rot"]], ["HMS Trincomalee of 1817 still floats", ["trincomalee", "1817", "afloat", "floats"]]],
    mcq: { q: "Why did ships built in Bombay last so long?", o: ["They were built of teak, which resists rot better than oak", "They were covered in iron plates", "They sailed only in calm seas", "They were rebuilt every ten years"] },
    bring: "When the Parsis come up: “The Wadias built warships in Bombay for the British Navy. One from 1817 is still floating in England.”",
    follow: "Which Indian-made product today do you think is better than the foreign one?",
    deeper: "The family's yard built over 350 ships. The treaty that ended the First Opium War in 1842 was signed on board HMS Cornwallis, another Wadia ship built in Bombay. The Wadia Group, which later owned Bombay Dyeing, traces its start to 1736." },

  { id: "mh-bombay-high", type: "fact", domain: "economics", region: "mumbai", title: "Bombay High: oil under the sea", value: 4, cue: "petrol prices, ONGC, or oil imports",
    emoji: "🛢️", wiki: "Mumbai High Field",
    fact: "India's largest oil field lies under the Arabian Sea, about 160 km west of Mumbai. The drilling ship Sagar Samrat struck oil there in February 1974. Production began on 21 May 1976.",
    why: "The find came just after the 1973 oil shock, when world oil prices rose about four times. For decades Bombay High gave India a large share of its own oil.",
    mech: "In the 1960s an Indian and Soviet survey ship mapped the sea floor with sound waves. It found a large raised dome of rock deep under the sea bed. Oil and gas rise through rock and collect under such a dome. That raised shape is why the field is called a ‘High’. ONGC then bought a drilling rig, drilled into the dome and found oil.",
    models: ["margin-of-safety", "first-principles"],
    q: "What is Bombay High, and how was it found?",
    a: "It is India's largest oil field, about 160 km off Mumbai under the sea. A survey in the 1960s found a raised dome of rock where oil collects. The rig Sagar Samrat struck oil in 1974 and production began in 1976.",
    chain: [["An oil field about 160 km off Mumbai", ["160", "sea", "offshore", "arabian"]], ["A survey found a raised dome of rock", ["survey", "dome", "raised", "soviet", "sound"]], ["Sagar Samrat struck oil in 1974", ["sagar samrat", "1974", "struck", "drill"]], ["Production began in 1976", ["1976", "production"]]],
    mcq: { q: "Why is the oil field off Mumbai called a ‘High’?", o: ["The oil sits under a raised dome of rock below the sea bed", "The oil rigs are very tall", "It lies on a mountain top", "The price of its oil is high"] },
    bring: "When petrol prices come up: “India's biggest oil field is 160 km out in the sea from here. It was found in 1974, just after the oil shock.”",
    follow: "Do you know how much of its oil India still has to import?",
    deeper: "Output peaked in the late 1990s and has fallen since. India now imports well over 80% of its crude oil. On 27 July 2005, one day after the great Mumbai flood, a fire destroyed a main platform at Bombay High and killed at least 22 people." },

  { id: "mh-atal-setu", type: "fact", domain: "design", region: "mumbai", title: "Atal Setu: a bridge built around birds and ships", value: 3, cue: "the sea bridge to Navi Mumbai, or big construction projects",
    emoji: "🌉", wiki: "Mumbai Trans Harbour Link",
    fact: "Atal Setu opened on 12 January 2024. It is India's longest sea bridge, about 22 km long, with 16.5 km over the water. It joins Sewri in Mumbai to the mainland near Nhava Sheva and cost about 17,840 crore rupees.",
    why: "A trip that could take two hours now takes about 20 minutes. The design also had to protect flamingos, shipping lanes and a nuclear research centre.",
    mech: "Ships must pass under the bridge to reach the ports. So some spans have no pillars for up to 180 metres. Concrete would be too heavy for such a long gap. Engineers used a steel deck stiffened with ribs, called an orthotropic steel deck, which is strong but light. Near Sewri, noise barriers protect the flamingos on the mudflats. View barriers hide the Bhabha Atomic Research Centre.",
    models: ["first-principles", "bottlenecks"],
    q: "What is special about the design of Atal Setu?",
    a: "It is India's longest sea bridge, about 22 km, from Sewri to near Nhava Sheva. Light steel decks cross gaps of up to 180 metres so ships can pass. Noise barriers protect the flamingos and view barriers hide the atomic research centre.",
    chain: [["India's longest sea bridge, about 22 km", ["22 km", "longest", "16.5"]], ["Sewri to the mainland near Nhava Sheva", ["sewri", "nhava", "mainland", "navi mumbai"]], ["Light steel decks span up to 180 m for ships", ["steel", "180", "ships", "span"]], ["Barriers for flamingos and the atomic centre", ["flamingo", "barrier", "atomic", "noise"]]],
    mcq: { q: "Why were steel decks used for the longest spans of Atal Setu?", o: ["Steel is light and strong, so it can cross wide gaps for ships", "Steel is cheaper than concrete", "Steel does not rust in sea water", "Concrete was not allowed near the port"] },
    bring: "On the sea bridge: “The noise walls at the Sewri end are for the flamingos. The view walls are for the atomic centre.”",
    follow: "Do you think the bridge will move people out to Navi Mumbai, or bring more cars in?",
    deeper: "Its full name is Atal Bihari Vajpayee Sewri-Nhava Sheva Atal Setu, and it is also called the Mumbai Trans Harbour Link. It has six lanes and was designed to last over 100 years. The idea of a bridge across the harbour was first studied in the 1960s." },

  { id: "mh-sgnp-leopards", type: "concept", domain: "science", region: "mumbai", title: "The leopards that live inside Mumbai", value: 5, cue: "Aarey, Borivali national park, or wild animals in cities",
    emoji: "🐆", wiki: "Sanjay Gandhi National Park",
    fact: "Sanjay Gandhi National Park is about 104 square km of forest inside Mumbai. A camera study in 2018 counted 47 adult leopards in and around it. That is one of the highest leopard densities recorded anywhere in the world.",
    why: "Wild big cats walk at night past housing societies in a city of over 20 million people. Most residents never see them.",
    mech: "The leopards hunt deer in the forest, but stray dogs make up a large part of their food. Dogs gather where rubbish is dumped at the forest edge. In the early 2000s attacks on people rose sharply. Research led by Vidya Athreya found a likely cause. Leopards caught elsewhere were being released into the park, and stressed animals in a strange place attack more. When that stopped and rubbish was managed better, attacks fell.",
    models: ["second-order-thinking", "feedback-loops", "incentives"],
    q: "How do leopards survive inside Mumbai, and why did attacks rise and then fall?",
    a: "About 47 leopards live in and around the 104 square km park, and they eat many stray dogs that gather near rubbish. Attacks rose in the early 2000s when leopards caught elsewhere were released there. Attacks fell when that stopped.",
    chain: [["A 104 square km forest inside the city", ["104", "park", "forest", "inside"]], ["About 47 leopards, a very high density", ["47", "density", "leopards"]], ["Stray dogs and rubbish feed them", ["dog", "rubbish", "garbage", "waste"]], ["Releasing caught leopards there caused attacks", ["release", "relocat", "caught", "moved", "stress"]]],
    mcq: { q: "What was found to be a likely cause of leopard attacks around the park in the early 2000s?", o: ["Leopards caught elsewhere were being released into the park", "The leopards had no water in summer", "Too many tourists fed them", "A disease made them aggressive"] },
    bring: "When Aarey or Borivali comes up: “Around 47 leopards live in that forest. They mostly eat stray dogs, and most of us never see them.”",
    follow: "Would you feel safe living next to the park?",
    deeper: "The park also holds the Kanheri caves, cut by Buddhist monks about 2,000 years ago. Tulsi and Vihar lakes, two of Mumbai's water sources, lie inside it. More than 20 lakh people visit the park each year." },

  { id: "mh-plague-1896", type: "event", domain: "history", region: "mumbai", title: "The plague of 1896 and the city it rebuilt", value: 5, cue: "epidemics, lockdowns, chawls, or how Dadar was planned",
    emoji: "🐀", wiki: "Bombay plague epidemic",
    fact: "In September 1896 Dr Acacio Viegas found bubonic plague in the crowded Mandvi area of Bombay. By early 1897 about half the people had left the city. In 1898 the government set up the Bombay City Improvement Trust to rebuild the crowded areas.",
    why: "Wide roads like Princess Street, planned suburbs like Dadar and Matunga, and a law used again in 2020 all came out of this epidemic.",
    mech: "Plague spread fastest in dark, packed houses near the docks, where rats and their fleas lived close to people. Officials decided that crowding and bad air were the problem. The Trust cut wide streets to bring in sea air, cleared slums and built chawls for workers. It also laid out new suburbs to the north. The scientist Waldemar Haffkine made a plague vaccine in Bombay and tested it on himself in January 1897.",
    models: ["second-order-thinking", "bottlenecks"],
    q: "How did the plague of 1896 change Bombay?",
    a: "Plague was found in crowded Mandvi in 1896 and about half the people fled. The Improvement Trust of 1898 cut wide streets, built chawls and planned suburbs like Dadar. Haffkine made a vaccine in Bombay in 1897.",
    chain: [["Plague found in crowded Mandvi in 1896", ["1896", "mandvi", "viegas", "plague"]], ["About half the people left the city", ["half", "fled", "left the city"]], ["The Improvement Trust rebuilt the city from 1898", ["trust", "1898", "wide", "street", "chawl", "suburb"]], ["Haffkine made a vaccine in Bombay", ["haffkine", "vaccine"]]],
    mcq: { q: "What was set up in 1898 because of the plague in Bombay?", o: ["The Bombay City Improvement Trust", "The Bombay Stock Exchange", "The Reserve Bank of India", "The first cotton mill"] },
    bring: "When Covid lockdowns come up: “The law used in 2020 was written for the Bombay plague of 1897. So were Dadar's planned streets.”",
    follow: "What do you think Covid will have changed in our cities fifty years from now?",
    deeper: "The Epidemic Diseases Act of 1897 gave officials wide powers to search homes and isolate people, and their harsh methods caused great anger. India used the same Act during Covid-19. Haffkine's laboratory later became the Haffkine Institute in Parel." },

  { id: "mh-elephanta", type: "place", domain: "history", region: "mumbai", title: "Elephanta: the island named after a lost elephant", value: 4, cue: "the ferry from the Gateway, old temples, or UNESCO sites",
    emoji: "🗿", wiki: "Elephanta Caves",
    fact: "The cave temples on Elephanta island were cut into rock around the middle of the 6th century. The great three-faced Shiva there, called the Sadashiva or Trimurti, is about 6 metres tall. The caves became a UNESCO World Heritage Site in 1987.",
    why: "One of the finest sculptures in India is an hour by boat from the Gateway. Yet the island's famous name comes from a statue that is no longer there.",
    mech: "The island's own name is Gharapuri. The Portuguese found a large stone elephant near the landing place and named the island after it. The temple was not built up from blocks. Workers cut into the hill and carved halls, pillars and statues out of the solid basalt. The three faces show Shiva as creator, protector and destroyer.",
    models: ["map-vs-territory", "lindy-effect"],
    q: "What are the Elephanta caves, and how did the island get its name?",
    a: "They are cave temples to Shiva cut from solid rock in about the 6th century, with a three-faced Shiva about 6 metres tall. The island is really Gharapuri. The Portuguese named it after a stone elephant they found there.",
    chain: [["Cave temples cut from rock in the 6th century", ["6th century", "cut", "carved", "rock", "cave"]], ["A three-faced Shiva about 6 metres tall", ["three-faced", "three faces", "shiva", "trimurti", "6 metres"]], ["The real name is Gharapuri", ["gharapuri"]], ["The Portuguese named it after a stone elephant", ["portug", "elephant"]]],
    mcq: { q: "Why is Gharapuri island called Elephanta?", o: ["The Portuguese found a large stone elephant there", "Wild elephants once lived on it", "The island is shaped like an elephant", "A king kept his war elephants there"] },
    bring: "At the Gateway ferry: “The elephant that gave Elephanta its name is not on the island. It stands in the Byculla zoo garden.”",
    follow: "Have you taken the ferry to Elephanta, or is it one of those places we never visit?",
    deeper: "The stone elephant broke when the British tried to move it in 1864. It was put together again and now stands at Jijamata Udyan in Byculla. Nobody knows for certain which king had the caves made. Many scholars point to the Kalachuri dynasty." },

  { id: "mh-irani-cafes", type: "fact", domain: "business", region: "mumbai", title: "The Irani cafés", value: 3, cue: "bun maska, old restaurants, or family businesses closing",
    emoji: "☕", wiki: "Irani café",
    fact: "Irani cafés were opened by Zoroastrians who came from Iran to Bombay in the 1800s and early 1900s. In the 1950s the city had about 350 of them. By the 2000s only about 25 were left.",
    why: "For decades these cafés were where a clerk, a student and a taxi driver could all sit over the same cheap tea. Their decline shows how a city's land prices can end a good business.",
    mech: "The Iranis arrived poor and many began by selling tea. Their cafés were cheap and open to people of every religion and class, which was unusual then. Many stood on street corners. It is said that other shopkeepers thought corner plots unlucky, so they were cheaper to rent. Later the land became very valuable, and many of the owners' children chose other careers. Selling or closing made more sense than serving tea.",
    models: ["opportunity-cost", "lindy-effect"],
    q: "Who started the Irani cafés, and why have most of them closed?",
    a: "Zoroastrians from Iran opened them in Bombay as cheap cafés open to everyone, often on corner plots. There were about 350 in the 1950s and only about 25 remain. The land became too valuable, and the children chose other careers.",
    chain: [["Opened by Zoroastrians from Iran", ["iran", "zoroastrian"]], ["Cheap and open to everyone", ["cheap", "everyone", "every religion", "class", "open to"]], ["From about 350 to about 25", ["350", "25"]], ["Valuable land and children choosing other work", ["land", "valuable", "children", "career", "rent"]]],
    mcq: { q: "Who opened Mumbai's Irani cafés?", o: ["Zoroastrians who came from Iran", "Portuguese bakers from Goa", "British army cooks", "Traders from Iraq"] },
    bring: "Over bun maska: “In the 1950s Bombay had about 350 Irani cafés. Only about 25 are left.”",
    follow: "Which old Mumbai eating place would you be sad to lose?",
    deeper: "Iranis are separate from the Parsis, who are also Zoroastrians but came to India about a thousand years earlier. Kyani and Co. at Dhobi Talao dates from 1904 and Britannia and Co. at Ballard Estate from 1923." },

  { id: "mh-docks-explosion", type: "historical story", domain: "history", region: "mumbai", title: "The Bombay docks explosion of 1944", value: 5, cue: "the docks, the fire brigade, or disasters caused by delay", story: "mh-docks",
    emoji: "💥", wiki: "1944 Bombay explosion",
    fact: "On 14 April 1944 the cargo ship Fort Stikine caught fire in Victoria Dock, Bombay. It carried about 1,400 tonnes of explosives, cotton bales and gold bars. It blew up at 4:06 pm and again at 4:34 pm. Between 800 and 1,300 people died.",
    why: "It was one of the worst disasters in the city's history. India marks 14 April as National Fire Service Day in memory of the firemen who died.",
    mech: "Cotton bales had been loaded below the explosives, and the cotton began to burn. Smoke was seen at about 2 pm. For two hours firemen poured water into the hold but could not reach the fire. Nobody gave a clear order to sink the ship or tow it out to sea. When the flames reached the explosives, the ship blew apart. Burning cotton and metal rained on the docks and nearby homes.",
    models: ["margin-of-safety", "second-order-thinking", "inversion"],
    q: "What caused the Bombay docks explosion of 1944, and why was it so deadly?",
    a: "The ship Fort Stikine carried cotton stored below about 1,400 tonnes of explosives. The cotton caught fire on 14 April 1944. For two hours nobody ordered the ship sunk or moved, and it exploded twice, killing 800 to 1,300 people, including 66 firemen.",
    chain: [["Fort Stikine carried explosives, cotton and gold", ["fort stikine", "explosive", "cotton", "gold"]], ["The cotton below the explosives caught fire", ["caught fire", "burn", "smoke", "fire"]], ["Two hours passed with no clear order", ["two hours", "order", "nobody", "delay", "sink"]], ["Two explosions killed 800 to 1,300 people", ["800", "1,300", "exploded", "blew", "4:06"]]],
    mcq: { q: "What was the Fort Stikine carrying when it caught fire in Bombay in 1944?", o: ["Explosives, cotton bales and gold bars", "Crude oil from the Gulf", "Coal and iron ore", "Only passengers and mail"] },
    bring: "On Fire Service Day or near the docks: “In 1944 a burning ship full of explosives sat in the dock for two hours. Nobody ordered it sunk.”",
    follow: "In an emergency at your workplace, is it clear who has the power to decide?",
    deeper: "Sixty-six firemen of the Bombay Fire Brigade were killed. About 13 ships were lost and around 80,000 people were left homeless. Gold bars from the ship were still being found during dredging of the docks as late as 2011." },

  { id: "mh-mumbai-water", type: "concept", domain: "geography", region: "mumbai", title: "Mumbai drinks from seven far-away lakes", value: 4, cue: "water cuts, lake levels in the news, or tanker water",
    emoji: "🚰", wiki: "Vihar Lake",
    fact: "Mumbai gets about 4,000 million litres of water a day from seven lakes: Tulsi, Vihar, Tansa, Modak Sagar, Upper Vaitarna, Middle Vaitarna and Bhatsa. Most lie in Thane, Palghar and Nashik districts. The farthest is over 100 km away.",
    why: "The city has almost no water source of its own. One monsoon over distant hills fills the taps for the whole year.",
    mech: "The lakes sit in the hills where the Western Ghats catch heavy monsoon rain. Dams hold the water of about four months for use over twelve. The lakes are higher than the city, so most of the water flows down the long pipes by gravity. Bhatsa alone gives about half the supply. A large share, often put at about a third, is lost through leaks and theft on the way.",
    models: ["margin-of-safety", "bottlenecks"],
    q: "Where does Mumbai's water come from, and how does it reach the city?",
    a: "It comes from seven lakes, most of them far outside the city, the farthest over 100 km away. Dams store the monsoon rain for the whole year, and gravity carries most of it down long pipes. About 4,000 million litres arrive each day.",
    chain: [["Seven lakes supply the city", ["seven", "7", "lakes"]], ["Most are far away, up to 100 km", ["100 km", "far", "thane", "nashik", "outside"]], ["Dams store monsoon rain for the year", ["monsoon", "dam", "store", "rain"]], ["Gravity carries it down long pipes", ["gravity", "pipe", "flows down"]]],
    mcq: { q: "Where does most of Mumbai's tap water come from?", o: ["Lakes in the hills, some over 100 km away", "Wells and borewells inside the city", "Sea water made fresh in a plant", "The Mithi river"] },
    bring: "When a water cut is announced: “Our water comes from seven lakes, some over 100 km away. One monsoon has to last the whole year.”",
    follow: "Do you know which lake the water in your tap comes from?",
    deeper: "Vihar was the first, finished in 1860 as the city's first piped water scheme. Tulsi and Vihar lie inside Sanjay Gandhi National Park. The Mithi river begins from the overflow of Vihar and Powai lakes." },

  /* ---------- Maharashtra ---------- */

  { id: "mh-ganesh-tilak", type: "event", domain: "history", region: "maharashtra", title: "How Ganeshotsav became a public festival", value: 5, cue: "Ganpati mandals, Lokmanya Tilak, or bringing people together",
    emoji: "🐘", wiki: "Ganesh Chaturthi",
    fact: "Until the 1890s, Ganesh Chaturthi in Maharashtra was mostly a family festival at home. In 1892 Bhausaheb Rangari set up a public Ganesh idol in Pune. In 1893 Lokmanya Bal Gangadhar Tilak praised the idea in his newspaper Kesari and worked to spread it.",
    why: "The pandals, processions and neighbourhood mandals that seem very old are about 130 years old. They began partly as a way to bring people together under British rule.",
    mech: "The British government watched political meetings closely, but it was careful about interfering with a religious festival. Tilak saw that a ten-day public festival could gather people of many castes in one place. Songs, plays and speeches at the festival could carry ideas about self-rule. Each neighbourhood formed its own mandal, so the festival spread quickly from Pune to Bombay and beyond.",
    models: ["network-effects", "game-theory", "social-proof"],
    q: "How and why did Ganeshotsav become a public festival?",
    a: "It was mostly a home festival until Bhausaheb Rangari set up a public idol in Pune in 1892 and Tilak promoted the idea from 1893. A religious festival could gather people of many castes when political meetings were watched. Mandals spread it from Pune to Bombay.",
    chain: [["It was mostly a home festival before", ["home", "family", "private"]], ["Rangari in 1892 and Tilak in 1893 made it public", ["tilak", "1893", "rangari", "1892", "public"]], ["A religious festival was harder for the British to stop", ["british", "religious", "political", "watched"]], ["It gathered many castes and spread through mandals", ["caste", "gather", "mandal", "together", "spread"]]],
    mcq: { q: "Who promoted Ganeshotsav as a large public festival in the 1890s?", o: ["Lokmanya Tilak", "Chhatrapati Shivaji Maharaj", "Mahatma Gandhi", "Dr B. R. Ambedkar"] },
    bring: "During Ganpati: “The public festival is only about 130 years old. Before the 1890s most people kept Ganpati at home.”",
    follow: "Does your building's mandal still bring neighbours together, or is it mostly a show now?",
    deeper: "Mumbai's oldest public Ganpati is at Keshavji Naik Chawl in Girgaon, begun in 1893. People still argue about how to share the credit between Rangari and Tilak. Tilak is also remembered for the line “Swaraj is my birthright and I shall have it.”" },

  { id: "mh-dnyaneshwari", type: "person", domain: "language", region: "maharashtra", title: "Sant Dnyaneshwar and the Dnyaneshwari", value: 5, cue: "Marathi literature, the Bhagavad Gita, or making knowledge open to all",
    emoji: "📜", wiki: "Dnyaneshwar",
    fact: "In 1290 Sant Dnyaneshwar, then about 15 years old, composed the Dnyaneshwari at Nevasa. It explains the Bhagavad Gita in about 9,000 Marathi verses. It is among the oldest great works in the Marathi language.",
    why: "Before this, the Gita could be read only by those who knew Sanskrit. He put its ideas into the language that farmers and traders spoke.",
    mech: "Sanskrit was the language of scholars and priests, and most people could not understand it. Dnyaneshwar chose Marathi and a simple verse form called the ovi, which people could sing and remember. He used examples from daily life to explain hard ideas. Because people could sing it, the text spread from mouth to mouth. It became the base of the Varkari tradition.",
    models: ["first-principles", "network-effects"],
    q: "What is the Dnyaneshwari, and why was it important?",
    a: "It is Sant Dnyaneshwar's explanation of the Bhagavad Gita in about 9,000 Marathi verses, composed in 1290 when he was about 15. Sanskrit was known only to scholars. By using Marathi and the ovi verse, he opened the Gita to common people.",
    chain: [["Composed by Sant Dnyaneshwar in 1290, aged about 15", ["1290", "dnyaneshwar", "15"]], ["It explains the Bhagavad Gita", ["gita"]], ["In Marathi, not Sanskrit", ["marathi", "sanskrit"]], ["Simple verses let common people learn it", ["ovi", "verse", "common people", "sing"]]],
    mcq: { q: "What did Sant Dnyaneshwar do in the Dnyaneshwari?", o: ["Explained the Bhagavad Gita in Marathi verse", "Translated the Quran into Marathi", "Wrote the history of the Maratha kings", "Wrote the first Marathi dictionary"] },
    bring: "When Marathi literature comes up: “The Dnyaneshwari was composed in 1290 by a boy of about 15. He wanted ordinary people to understand the Gita.”",
    follow: "Which hard subject today most needs someone to explain it in plain language?",
    deeper: "He is said to have taken samadhi at Alandi near Pune in 1296, at about 21. The work ends with the Pasaydan, a short prayer for the good of all living beings, which is still sung across Maharashtra." },

  { id: "mh-wari", type: "concept", domain: "anthropology", region: "maharashtra", title: "The Pandharpur Wari", value: 5, cue: "Ashadhi Ekadashi, Vitthal, or very old traditions",
    emoji: "🚩", wiki: "Pandharpur Wari",
    fact: "Every year about ten lakh people walk to Pandharpur to reach the temple of Vithoba on Ashadhi Ekadashi. The two main groups start from Alandi and Dehu near Pune. They walk about 250 km in about 21 days. The tradition is over 700 years old.",
    why: "It is one of the largest and oldest walking pilgrimages in the world. It runs every year with very little help from any central authority.",
    mech: "The walkers are called Varkaris. They move in groups called dindis, often from one village. Each dindi arranges its own food, tents and place in the line. They carry the padukas, or sandals, of Sant Dnyaneshwar and Sant Tukaram in palkhis and sing their abhangas on the way. The saints taught that devotion matters more than birth or wealth. So on the road people of many castes walk and eat together.",
    models: ["lindy-effect", "network-effects"],
    q: "What is the Pandharpur Wari, and how is it organised?",
    a: "About ten lakh Varkaris walk around 250 km in 21 days from Alandi and Dehu to the Vithoba temple at Pandharpur for Ashadhi Ekadashi. They walk in self-run groups called dindis and carry the padukas of Sant Dnyaneshwar and Sant Tukaram in palkhis.",
    chain: [["A walk to Vithoba's temple at Pandharpur", ["pandharpur", "vithoba", "vitthal"]], ["About 250 km in 21 days from Alandi and Dehu", ["250", "21 days", "alandi", "dehu"]], ["Self-run groups called dindis", ["dindi", "group"]], ["Palkhis carry the saints' padukas", ["palkhi", "paduka", "sandal", "dnyaneshwar", "tukaram"]]],
    mcq: { q: "What do the palkhis in the Pandharpur Wari carry?", o: ["The padukas of Sant Dnyaneshwar and Sant Tukaram", "Gold for the temple", "The idol of Vithoba from Pune", "Food for the whole journey"] },
    bring: "Around Ashadhi Ekadashi: “About ten lakh people are walking 250 km to Pandharpur right now. They have done it for over 700 years.”",
    follow: "Have you or anyone in your family ever walked even one day of the Wari?",
    deeper: "The palkhi form began in 1685 with Narayan Maharaj, the youngest son of Sant Tukaram. Haibatbaba Arphalkar gave it today's organised shape in the 1820s. Sant Tukaram lived in Dehu in the 1600s and composed thousands of abhangas in everyday Marathi." },

  { id: "mh-bajirao", type: "person", domain: "strategy", region: "maharashtra", title: "Bajirao I and the speed of cavalry", value: 4, cue: "speed against size, the Peshwas, or moving faster than a rival",
    emoji: "🐎", wiki: "Bajirao I",
    fact: "Bajirao I became Peshwa, the Maratha prime minister, in 1720 at the age of 20. In 1728 at Palkhed he trapped the much heavier army of the Nizam of Hyderabad without a big battle. Field Marshal Montgomery later called this campaign “a masterpiece of strategic mobility”.",
    why: "He showed that an army's speed can matter more than its size or its guns.",
    mech: "The Nizam's army moved slowly, with heavy cannon and a long line of carts. Bajirao's force was almost all horsemen. They carried little baggage, took food from the land, and had spare horses. He rode far ahead and threatened the Nizam's own lands, so the Nizam had to chase him. Then he cornered the tired army near Palkhed, in a dry place cut off from food and water. The Nizam had to sign a treaty.",
    models: ["bottlenecks", "inversion"],
    q: "How did Bajirao I defeat the Nizam at Palkhed in 1728?",
    a: "His light cavalry carried little baggage and moved far faster than the Nizam's army with its heavy cannon. He made the Nizam chase him, then trapped him near Palkhed without food and water. The Nizam signed a treaty without a big battle.",
    chain: [["Peshwa at 20, in 1720", ["1720", "peshwa", "20"]], ["Light cavalry with little baggage moved fast", ["cavalry", "horse", "baggage", "fast", "light"]], ["The Nizam's army was slow with heavy cannon", ["nizam", "cannon", "slow", "heavy"]], ["Trapped at Palkhed without food and water", ["palkhed", "trap", "water", "cut off", "corner"]]],
    mcq: { q: "What was Bajirao I's main advantage over the Nizam in 1728?", o: ["Fast cavalry that carried little baggage", "Bigger cannon", "A much larger army", "Help from the British"] },
    bring: "When a small, fast company beats a big one: “Bajirao did this in 1728. His horsemen carried almost nothing, so the Nizam's heavy army could never catch them.”",
    follow: "Where in your work does carrying less let you move faster?",
    deeper: "The treaty was signed at Mungi Shevgaon in March 1728. Bajirao died in 1740 at only 39, on campaign near the Narmada river. It is often said that he never lost a battle, though historians do not all agree on this." },

  { id: "mh-ahilyabai", type: "person", domain: "history", region: "maharashtra", title: "Ahilyabai Holkar", value: 4, cue: "women rulers, the Kashi Vishwanath temple, or good government",
    emoji: "👑", wiki: "Ahilyabai Holkar",
    fact: "Ahilyabai Holkar was born in 1725 in Chondi village, in today's Ahilyanagar district of Maharashtra. She ruled the Holkar kingdom of Malwa from 1767 to 1795, with her capital at Maheshwar. She rebuilt the Kashi Vishwanath temple in Varanasi in 1780.",
    why: "A village girl became one of the most respected rulers of the 1700s, at a time when widows were expected to stay out of public life.",
    mech: "Her husband Khanderao was killed in battle in 1754. By tradition her father-in-law Malhar Rao Holkar persuaded her not to commit sati, and trained her in the work of the state. After he died, she took charge. She heard people's complaints herself and kept taxes fair. She used her wealth to build temples, ghats, wells and rest houses for travellers across India. Her general Tukoji Holkar led the army.",
    models: ["second-order-thinking", "incentives"],
    q: "Who was Ahilyabai Holkar, and what is she remembered for?",
    a: "She was born in Chondi in Maharashtra in 1725 and ruled Malwa from Maheshwar from 1767 to 1795 after her husband and father-in-law died. She was known for fair rule. She built temples, ghats and wells across India, and rebuilt the Kashi Vishwanath temple in 1780.",
    chain: [["Born in Chondi, Maharashtra, in 1725", ["chondi", "1725", "maharashtra"]], ["Trained by her father-in-law Malhar Rao after her husband died", ["malhar", "father-in-law", "husband", "widow"]], ["Ruled Malwa from Maheshwar, 1767 to 1795", ["maheshwar", "malwa", "1767", "1795"]], ["Built temples, ghats and wells across India", ["temple", "kashi", "ghat", "wells"]]],
    mcq: { q: "Which famous temple did Ahilyabai Holkar rebuild in 1780?", o: ["Kashi Vishwanath in Varanasi", "The Sun Temple at Konark", "Meenakshi temple in Madurai", "The Golden Temple in Amritsar"] },
    bring: "When Ahilyanagar or Varanasi comes up: “The Kashi Vishwanath temple of today was rebuilt in 1780 by Ahilyabai Holkar, who was born in a Maharashtra village.”",
    follow: "Which ruler from history do you think governed best in peace, not in war?",
    deeper: "Ahmednagar district was renamed Ahilyanagar in her honour, a change the state approved in 2024. She also encouraged weavers to settle at Maheshwar, and Maheshwari saris are still made there. Indore airport carries her name." },

  { id: "mh-satyashodhak", type: "event", domain: "philosophy", region: "maharashtra", title: "Jyotirao Phule and the Satyashodhak Samaj", value: 5, cue: "caste, social reform, or who is allowed to have knowledge",
    emoji: "⚖️", wiki: "Jyotirao Phule",
    fact: "On 24 September 1873 Jyotirao Phule founded the Satyashodhak Samaj, the ‘Society of Truth Seekers’, in Pune. It worked for the education and equal rights of lower castes and women. In the same year he published his book Gulamgiri, which means slavery.",
    why: "It was one of the first movements in India led by lower-caste people themselves, and it shaped the reformers who came after.",
    mech: "Phule argued that caste survived because a few people controlled both knowledge and religious ceremonies. So the Samaj attacked both. It opened schools and pushed for schooling for all. Its members held weddings and other ceremonies in simple Marathi, without a priest. This showed that people did not need a middleman to reach God. The idea spread through villages and through its newspaper, Deenbandhu.",
    models: ["first-principles", "incentives", "inversion"],
    q: "What was the Satyashodhak Samaj, and how did it challenge caste?",
    a: "Jyotirao Phule founded it in Pune in 1873 to win education and equal rights for lower castes and women. He said caste rested on control of knowledge and ceremonies. So the Samaj spread schooling and held weddings without priests.",
    chain: [["Founded by Jyotirao Phule in Pune in 1873", ["1873", "phule", "pune"]], ["For education and equal rights of lower castes and women", ["education", "equal", "women", "lower caste", "school"]], ["Caste rested on control of knowledge and ceremonies", ["control", "knowledge", "ceremon"]], ["Weddings without priests", ["without priest", "without a priest", "wedding", "middleman"]]],
    mcq: { q: "What does ‘Satyashodhak Samaj’ mean?", o: ["Society of Truth Seekers", "Society of Farmers", "Society for Self-Rule", "Society of Teachers"] },
    bring: "When caste or reform comes up: “Phule dedicated his 1873 book Gulamgiri to the Americans who had ended slavery. He saw it as the same fight.”",
    follow: "Which ‘middlemen’ today still control access to knowledge?",
    deeper: "He was given the title Mahatma at a public meeting in Bombay in 1888, long before Gandhi was called by that name. In the early 1900s Chhatrapati Shahu Maharaj of Kolhapur supported the movement. Dr B. R. Ambedkar counted Phule among his teachers." },

  { id: "mh-sugar-coops", type: "business concept", domain: "economics", region: "maharashtra", title: "The sugar cooperatives of western Maharashtra", value: 4, cue: "sugar prices, sugarcane, drought, or cooperatives",
    emoji: "🍬", wiki: "Cooperative sugar factories in Maharashtra",
    fact: "In 1950 farmers at Pravaranagar in Ahmednagar district started what is known as Asia's first cooperative sugar factory, led by Vithalrao Vikhe Patil. Today Maharashtra makes about a third of India's sugar, much of it in farmer-owned factories.",
    why: "The cooperatives made many cane farmers richer and built schools, banks and colleges. They also tied a dry state to a very thirsty crop.",
    mech: "Before, private mills and moneylenders took most of the profit. In a cooperative the cane farmers own the factory and share what it earns. A sure buyer and a good price made more and more farmers plant cane. But sugarcane needs water all year. It grows on under 4% of the state's cropped land, yet it is estimated to use about 70% of the irrigation water. In drought years that leaves little for other crops.",
    models: ["incentives", "second-order-thinking", "feedback-loops"],
    q: "How did sugar cooperatives change western Maharashtra, for better and for worse?",
    a: "From 1950 at Pravaranagar, cane farmers owned their own factories and shared the profit, which raised incomes and made more farmers plant cane. But cane uses about 70% of the irrigation water on under 4% of the land, so other crops go short.",
    chain: [["First cooperative sugar factory at Pravaranagar in 1950", ["1950", "pravara", "vikhe"]], ["Farmers own the factory and share the profit", ["own", "share", "cooperative", "profit"]], ["A sure buyer made more farmers plant cane", ["more farmers", "plant", "sure buyer", "price", "incomes"]], ["Cane takes about 70% of irrigation water on 4% of land", ["70%", "4%", "water", "thirsty"]]],
    mcq: { q: "What is the main cost of Maharashtra's sugarcane boom?", o: ["Cane uses a very large share of the state's irrigation water", "Sugar factories have polluted the sea", "Farmers stopped owning land", "India has to import sugar"] },
    bring: "When drought news comes up: “Sugarcane is on less than 4% of the farmland in Maharashtra but takes about 70% of the irrigation water.”",
    follow: "If a crop pays farmers well but drains the water, who should decide whether to grow it?",
    deeper: "The economist D. R. Gadgil helped set up the Pravara factory. Many of the state's political leaders rose through sugar cooperatives. The 70% figure comes from a central government farm prices commission and is an estimate." },

  { id: "mh-warli", type: "concept", domain: "design", region: "maharashtra", title: "Warli painting: a whole world from three shapes", value: 3, cue: "tribal art, Palghar, or simple design",
    emoji: "🎨", wiki: "Warli painting",
    fact: "Warli painting comes from the Warli tribal community of Palghar district, north of Mumbai. It uses only white paint made from rice paste, on a red-brown mud wall. Almost everything is drawn with three shapes: the circle, the triangle and the square.",
    why: "With three shapes and one colour, the Warlis show weddings, harvests, dances and forests. It is a lesson in how much a strict limit can do.",
    mech: "The circle stands for the sun and moon. The triangle comes from hills and pointed trees. Two triangles joined at the tip make a human body. The square marks a sacred space. Women traditionally painted these on house walls for weddings. In the 1970s the artist Jivya Soma Mashe began to paint daily life on paper and cloth, and the art became known around the world.",
    models: ["first-principles"],
    q: "How does Warli painting work, and how did it become famous?",
    a: "Warlis of Palghar paint with white rice paste on mud walls, using only the circle, triangle and square. Two triangles make a person. Women painted them for weddings. Jivya Soma Mashe took the art onto paper in the 1970s and made it known worldwide.",
    chain: [["From the Warli community of Palghar", ["warli", "palghar", "tribal"]], ["White rice paste on a mud wall", ["rice", "white", "mud"]], ["Only circle, triangle and square", ["circle", "triangle", "square", "three shapes"]], ["Jivya Soma Mashe made it widely known", ["mashe", "1970", "paper", "known"]]],
    mcq: { q: "What is the white paint in traditional Warli painting made from?", o: ["Rice paste", "Lime from sea shells", "Chalk powder", "Milk and flour"] },
    bring: "When you see Warli art on a wall or a sari: “All of it is made from just a circle, a triangle and a square. Each person is two triangles.”",
    follow: "Could you explain your own work using only three simple shapes?",
    deeper: "Mashe received the Padma Shri in 2011 and died in 2018. Warli painting got a Geographical Indication tag in 2014. A well-known subject is the tarpa dance, in which villagers move in a spiral around a man playing a long horn." },

  { id: "mh-kolhapuri", type: "business concept", domain: "business", region: "maharashtra", title: "Kolhapuri chappals and the GI tag", value: 4, cue: "Indian crafts, brands copying designs, or GI tags",
    emoji: "🩴", wiki: "Kolhapuri chappal",
    fact: "Kolhapuri chappals are handmade leather sandals. In 2019 they received a Geographical Indication tag covering eight districts: Kolhapur, Sangli, Satara and Solapur in Maharashtra, and four across the border in Karnataka. In June 2025 the Italian brand Prada showed very similar sandals in Milan.",
    why: "The Prada show started a national argument about who owns a traditional design, and who earns from it.",
    mech: "A GI tag says that a name belongs to goods made in a certain place in the traditional way. Real Kolhapuris use leather tanned with plant materials and are stitched by hand with leather cord, without nails. But a GI tag protects mainly the name, and mainly inside India. It does not stop a foreign company from selling a similar design under another name. After protests, Prada said the sandals were inspired by Indian handmade footwear.",
    models: ["moat", "map-vs-territory", "incentives"],
    q: "What does the GI tag on Kolhapuri chappals protect, and what did the Prada case show?",
    a: "The 2019 GI tag says that only handmade sandals from eight districts of Maharashtra and Karnataka can be called Kolhapuri. It protects the name, mainly within India. Prada could still show a similar design in 2025, and only admitted the Indian inspiration after protests.",
    chain: [["Handmade leather sandals from Kolhapur and nearby", ["handmade", "leather", "kolhapur", "hand"]], ["GI tag in 2019 for eight districts in two states", ["2019", "gi tag", "eight", "karnataka"]], ["The tag protects the name, mainly inside India", ["name", "inside india", "within india", "protects"]], ["Prada showed a similar design in 2025", ["prada", "2025", "similar"]]],
    mcq: { q: "What does a GI tag mainly protect?", o: ["The use of a name for goods from a certain place", "The price of the product", "The design in every country of the world", "The workers' wages"] },
    bring: "When brands and copying come up: “Kolhapuris have a GI tag, but it protects the name, not the design. That is how Prada could show the same sandal in Milan.”",
    follow: "Should a company pay a craft community when it borrows a traditional design?",
    deeper: "GI stands for Geographical Indication. Darjeeling tea was the first Indian product to get one, in 2004. The Kolhapuri tag is shared with Karnataka because makers on both sides of the border have long made the same sandal." },

  { id: "mh-alphonso", type: "fact", domain: "science", region: "maharashtra", title: "The Alphonso mango is a Portuguese graft", value: 4, cue: "mango season, hapus prices, or Ratnagiri and Devgad",
    emoji: "🥭", wiki: "Alphonso mango",
    fact: "The Alphonso or hapus mango is named after Afonso de Albuquerque, the Portuguese general who took Goa in 1510. Portuguese Jesuit priests in Goa brought the skill of grafting to mango trees. That made it possible to produce and keep varieties like the Alphonso.",
    why: "The pride of the Konkan carries a Portuguese name. And every Alphonso tree is in effect a copy of one original tree.",
    mech: "A mango seed mixes the traits of two parent trees. So a tree grown from an Alphonso stone will usually not give Alphonso fruit. In grafting, a cut branch of a good tree is joined to the young root plant of another tree. The branch grows on, and its fruit is exactly like the parent's. By grafting again and again, growers kept the same taste for centuries.",
    models: ["first-principles", "compounding"],
    q: "Why is the Alphonso mango linked to the Portuguese, and why is it grown by grafting?",
    a: "It is named after Afonso de Albuquerque, and Portuguese Jesuits in Goa brought grafting to mango trees. A mango seed mixes two parents and does not copy the fruit. A grafted branch does, so every Alphonso tree is a copy.",
    chain: [["Named after Afonso de Albuquerque", ["afonso", "albuquerque", "named"]], ["Portuguese Jesuits in Goa brought grafting", ["jesuit", "portug", "goa"]], ["A seed mixes two parents and does not copy the fruit", ["seed", "stone", "mix", "parents"]], ["A grafted branch gives an exact copy", ["graft", "copy", "branch"]]],
    mcq: { q: "Why are Alphonso mango trees grown by grafting and not from seed?", o: ["A tree grown from seed usually does not give the same fruit", "Mango seeds cannot grow in the Konkan", "Grafted trees need no water", "The seeds are poisonous"] },
    bring: "In mango season: “Hapus comes from ‘Afonso’, a Portuguese general. And every Alphonso tree is a graft, a copy of an older tree.”",
    follow: "Do you think Devgad or Ratnagiri hapus is better?",
    deeper: "The Marathi word hapus is thought to come from the name Afonso. In 2018 Alphonso from Ratnagiri, Sindhudurg and nearby Konkan districts received a GI tag. The laterite soil and sea air of the Konkan are said to give the fruit its taste." },

  { id: "mh-koyna-quake", type: "scientific principle", domain: "science", region: "maharashtra", title: "Koyna 1967: the earthquake a dam may have caused", value: 4, cue: "dams, earthquakes in Maharashtra, or side effects of big projects",
    emoji: "🌊", wiki: "Koyna Dam",
    fact: "The Koyna dam in Satara district began to fill in 1962. At 4:21 am on 11 December 1967 an earthquake of about magnitude 6.5 struck right beside it. About 180 people died. It is the largest earthquake in the world that scientists link to a reservoir.",
    why: "The Deccan was thought to be solid, quiet rock. Koyna showed that a large lake made by people may be able to set off an earthquake.",
    mech: "Old cracks, called faults, lie deep in the rock and are held shut by friction. A full reservoir adds a huge weight of water on top. Water also seeps down into the cracks and pushes their sides apart, so they slip more easily. Small tremors began soon after the lake filled. In 1967 a large fault slipped. This effect is called reservoir-triggered seismicity. Small quakes still occur there as the lake level rises and falls.",
    models: ["second-order-thinking", "bayesian-thinking"],
    q: "What happened at Koyna in 1967, and how can a dam trigger an earthquake?",
    a: "An earthquake of about magnitude 6.5 struck beside the Koyna reservoir in December 1967, five years after it began to fill, and killed about 180 people. The weight of the water, and water seeping into old faults, lets them slip more easily.",
    chain: [["The Koyna reservoir began filling in 1962", ["1962", "reservoir", "fill", "dam"]], ["A quake of about 6.5 struck in December 1967", ["1967", "6.5", "earthquake"]], ["The weight of water presses on the rock", ["weight"]], ["Water seeps into faults so they slip", ["seep", "fault", "slip", "crack"]]],
    mcq: { q: "Why do many scientists link the 1967 Koyna earthquake to the dam?", o: ["The new reservoir's water changed the stress on old faults", "The dam was built on a volcano", "Blasting for the dam cracked the earth", "The dam broke and shook the ground"] },
    bring: "When dams or earthquakes come up: “The 1967 Koyna quake is the biggest in the world that scientists link to a reservoir. The lake had filled only five years before.”",
    follow: "What other big project had a side effect nobody planned for?",
    deeper: "The dam itself cracked but held, and it was later strengthened. Some project officials long disputed the link with the reservoir. Scientists have since drilled deep holes near Koyna to study the faults directly. The Koyna power project is a major source of electricity for Maharashtra." },

  { id: "mh-kaas", type: "place", domain: "geography", region: "maharashtra", title: "Kaas plateau: flowers on bare rock", value: 3, cue: "monsoon trips, Satara, or wildflowers",
    emoji: "🌸", wiki: "Kas Plateau Reserved Forest",
    fact: "Kaas plateau lies about 25 km from Satara, at a height of about 1,200 metres. For a few weeks from late August, it is covered with wildflowers. More than 850 kinds of flowering plants have been recorded there. It is part of the Western Ghats UNESCO World Heritage Site, listed in 2012.",
    why: "For most of the year it looks like dry, empty rock. The harsh ground is the very reason the flowers are so special.",
    mech: "The plateau is hard rock with only a very thin layer of soil, about 25 mm in places. Trees and tall grass cannot grow in it. So small plants face little competition. They have only the monsoon months to sprout, flower and make seed before the soil dries. Different plants flower one after another, so the colour of the plateau changes every week or two.",
    models: ["survivorship-bias", "bottlenecks"],
    q: "Why does Kaas plateau burst into flower for only a few weeks?",
    a: "It is hard rock near Satara with only a thin layer of soil, so trees cannot grow and small plants face little competition. They must flower and seed within the monsoon. More than 850 kinds grow there, and it is part of a UNESCO site.",
    chain: [["A rock plateau near Satara", ["satara", "plateau", "rock"]], ["Very thin soil, so no trees", ["thin", "soil", "tree"]], ["Small plants must flower in the short monsoon", ["monsoon", "few weeks", "august", "flower"]], ["Over 850 kinds, in a UNESCO site", ["850", "unesco"]]],
    mcq: { q: "Why can so many small flowering plants grow on Kaas plateau?", o: ["The soil is too thin for trees, so small plants face little competition", "Farmers plant new seeds every year", "The plateau has very deep, rich soil", "It gets rain all twelve months"] },
    bring: "When monsoon trips come up: “Kaas has flowers because the soil is too thin for trees. The bad ground is the reason for the beauty.”",
    follow: "Where else does a hard limit produce something special?",
    deeper: "To protect the plants, the number of visitors is limited to about 3,000 a day in the season, and booking is needed. Many of the plants are found only in the Western Ghats." },

  { id: "mh-konkan-railway", type: "historical story", domain: "design", region: "maharashtra", title: "Building the Konkan Railway", value: 5, cue: "train trips to Goa or Kokan, big projects, or E. Sreedharan", story: "mh-konkan",
    emoji: "🚆", wiki: "Konkan Railway",
    fact: "The Konkan Railway runs about 740 km along the coast from Roha in Maharashtra to near Mangaluru in Karnataka. It has over 2,000 bridges and more than 90 tunnels. Work began in 1990 under the engineer E. Sreedharan, and the full line opened on 26 January 1998.",
    why: "The British had judged this coast too hard for a railway. Indian engineers built the line in a little over seven years.",
    mech: "The Western Ghats send hundreds of rivers and steep ridges across the route. A flat, fast line therefore needed a bridge or tunnel every few hundred metres. A separate company, the Konkan Railway Corporation, was set up to move faster than a government department could. It raised part of the money by selling bonds to the public. Work started at many places at once. The hardest parts were tunnels through soft, wet clay, which kept collapsing.",
    models: ["first-principles", "bottlenecks"],
    q: "Why was the Konkan Railway so hard to build, and how was it done?",
    a: "The Western Ghats cross the coast with rivers and ridges, so the 740 km line needed over 2,000 bridges and more than 90 tunnels. A separate corporation under E. Sreedharan raised money through bonds and worked at many places at once. It opened in 1998.",
    chain: [["About 740 km from Roha to near Mangaluru", ["740", "roha", "mangal"]], ["Rivers and ridges of the Western Ghats cross the route", ["river", "ridge", "ghats", "hill"]], ["Over 2,000 bridges and more than 90 tunnels", ["2,000", "bridge", "tunnel", "90"]], ["A separate corporation under Sreedharan, opened 1998", ["sreedharan", "corporation", "bonds", "1998"]]],
    mcq: { q: "Why did the Konkan Railway need so many bridges and tunnels?", o: ["Rivers and steep ridges of the Western Ghats cross the route", "The line was built over the open sea", "Each state demanded its own tunnels", "The land along the coast was too expensive"] },
    bring: "On a train to Goa: “This line has over 2,000 bridges and 90 tunnels. It was built in about seven years, after the British had given up on it.”",
    follow: "Which of today's big projects do you think will be finished on time?",
    deeper: "The longest tunnel, at Karbude near Ratnagiri, is about 6.5 km long. The Panval viaduct near Ratnagiri stands on pillars up to 64 metres high. Land was taken from about 43,000 owners. Seventy-four workers died during construction." },

  { id: "mh-marathi-classical", type: "fact", domain: "language", region: "maharashtra", title: "Marathi as a classical language, and the Modi script", value: 4, cue: "Marathi pride, language debates, or old family documents",
    emoji: "✍️", wiki: "Modi script",
    fact: "On 3 October 2024 the central government gave Marathi the status of a classical language, along with Pali, Prakrit, Assamese and Bengali. For several hundred years, most Marathi letters and records were not written in Devanagari. They were written in a fast running script called Modi.",
    why: "Huge numbers of old papers, including land records and Peshwa-era letters, are in a script that very few Marathi speakers can read today.",
    mech: "To be called classical, a language must show early texts or records going back 1,500 to 2,000 years, and its own old literature. Modi was made for speed. One line runs along the top and the pen is seldom lifted, so clerks could write quickly. But its many joined shapes were hard to cast as metal type for printing. Devanagari was easier to print. In 1917 the Bombay government made Devanagari the official script, and Modi faded.",
    models: ["lindy-effect", "network-effects"],
    q: "What is the Modi script, and why did it disappear?",
    a: "Modi was a fast running script used for Marathi letters and records for several hundred years, written with the pen seldom lifted. It was hard to print, so Devanagari replaced it officially in 1917. Marathi itself was named a classical language in 2024.",
    chain: [["Marathi became a classical language in 2024", ["2024", "classical"]], ["Modi was a fast running script for Marathi records", ["modi", "running", "fast", "records"]], ["The pen was seldom lifted", ["pen", "lifted", "speed", "quickly"]], ["Hard to print, so Devanagari replaced it in 1917", ["print", "devanagari", "1917"]]],
    mcq: { q: "Why did the Modi script fall out of use?", o: ["It was hard to print, and Devanagari was easier", "The Peshwas banned it", "Nobody could write it quickly", "It had no vowels"] },
    bring: "When Marathi comes up: “Shivaji Maharaj's letters and the Peshwa records are in Modi, not Devanagari. Most of us could not read them today.”",
    follow: "Does your family have any old papers that nobody can read any more?",
    deeper: "By tradition Modi is linked to Hemadpant, a minister of the Yadava kings of Devagiri in the 1200s, but its true origin is uncertain. Maharashtra first asked for classical status in 2013. India now has eleven classical languages." }

